import axios from 'axios';

const API_KEYS = {
  newsapi: process.env.REACT_APP_NEWSAPI_KEY,
  nytimes: process.env.REACT_APP_NYTIMES_KEY,
  guardian: process.env.REACT_APP_GUARDIAN_KEY,
};

const fetchNews = async (query: string, source: string, date: string, category: string, author: string) => {
  let url = '';
  switch (source) {
    case 'newsapi':
      url = `https://newsapi.org/v2/everything?q=${query}&from=${date}&category=${category}&author=${author}&apiKey=${API_KEYS.newsapi}`;
      break;
    case 'nytimes':
      url = `https://api.nytimes.com/svc/search/v2/articlesearch.json?q=${query}&begin_date=${date.replace(/-/g, '')}&fq=news_desk:("${category}") AND byline:("${author}")&api-key=${API_KEYS.nytimes}`;
      break;
    case 'guardian':
      url = `https://content.guardianapis.com/search?q=${query}&from-date=${date}&section=${category}&api-key=${API_KEYS.guardian}&show-fields=all`;
      break;
  }
  const response = await axios.get(url);
  return response.data;
};

export { fetchNews };
